#include "ui_font.h"

#include <3ds.h>
#include <math.h>
#include <stdio.h>
#include <string.h>

// Sizes generated by tools/make_fonts.sh (must match that script).
static const int SIZES[] = { 11, 12, 13, 14, 15, 18 };
#define NSIZES ((int)(sizeof SIZES / sizeof *SIZES))

static C2D_Font fonts[NSIZES];
static float font_baseline[NSIZES];  // baseline offset from the top of a line, px
static float sys_line = 30.0f, sys_baseline = 24.0f;

static C2D_TextBuf draw_buf, measure_buf;

void font_init(void)
{
	draw_buf = C2D_TextBufNew(4096);
	measure_buf = C2D_TextBufNew(512);

	fontEnsureMapped();
	FINF_s *si = fontGetInfo(NULL);
	if (si) {
		if (si->lineFeed) sys_line = si->lineFeed;
		if (si->tglp) sys_baseline = si->tglp->baselinePos;
	}

	romfsInit();
	for (int i = 0; i < NSIZES; i++) {
		char path[64];
		snprintf(path, sizeof path, "romfs:/fonts/inter-%d.bcfnt", SIZES[i]);
		fonts[i] = C2D_FontLoad(path);
		if (!fonts[i]) continue;
		FINF_s *fi = C2D_FontGetInfo(fonts[i]);
		font_baseline[i] = fi && fi->tglp ? fi->tglp->baselinePos : SIZES[i] * 0.8f;
		// Drawn at exactly 1:1, so nearest sampling is both crisper and cheaper.
		C2D_FontSetFilter(fonts[i], GPU_NEAREST, GPU_NEAREST);
	}
}

void font_exit(void)
{
	for (int i = 0; i < NSIZES; i++) if (fonts[i]) C2D_FontFree(fonts[i]);
	romfsExit();
	C2D_TextBufDelete(measure_buf);
	C2D_TextBufDelete(draw_buf);
}

void font_frame_begin(void) { C2D_TextBufClear(draw_buf); }

// Exact size match, or -1 (then everything uses the scaled system font).
static int font_for(float px)
{
	int want = (int)floorf(px + 0.5f);
	for (int i = 0; i < NSIZES; i++)
		if (SIZES[i] == want && fonts[i]) return i;
	return -1;
}

static int utf8_next(const char *s, u32 *cp)
{
	const unsigned char *u = (const unsigned char *)s;
	if (u[0] < 0x80) { *cp = u[0]; return 1; }
	if ((u[0] & 0xE0) == 0xC0 && u[1]) { *cp = ((u[0] & 0x1F) << 6) | (u[1] & 0x3F); return 2; }
	if ((u[0] & 0xF0) == 0xE0 && u[1] && u[2]) {
		*cp = ((u[0] & 0x0F) << 12) | ((u[1] & 0x3F) << 6) | (u[2] & 0x3F); return 3;
	}
	if ((u[0] & 0xF8) == 0xF0 && u[1] && u[2] && u[3]) {
		*cp = ((u[0] & 0x07) << 18) | ((u[1] & 0x3F) << 12) | ((u[2] & 0x3F) << 6) | (u[3] & 0x3F); return 4;
	}
	*cp = '?';
	return 1;
}

static bool covered(int fi, u32 cp)
{
	if (fi < 0) return false;
	if (cp < 0x80) return true; // the generated fonts always include ASCII
	FINF_s *info = C2D_FontGetInfo(fonts[fi]);
	return C2D_FontGlyphIndexFromCodePoint(fonts[fi], cp) != info->alterCharIndex;
}

// Walks s as runs of same-font characters. For each run calls fn with the
// font (NULL = system), scale, and a NUL-terminated copy of the run.
typedef void (*run_fn)(C2D_Font f, float scale, float baseline, const char *run, void *ctx);

static void for_each_run(const char *s, float px, run_fn fn, void *ctx)
{
	int fi = font_for(px);
	float sys_scale = px / sys_line;
	char run[256];
	while (*s) {
		u32 cp;
		utf8_next(s, &cp);
		bool custom = covered(fi, cp);
		size_t n = 0;
		while (s[n]) {
			int len = utf8_next(s + n, &cp);
			if (covered(fi, cp) != custom || n + (size_t)len >= sizeof run) break;
			n += (size_t)len;
		}
		if (n == 0) n = 1; // guarantee progress
		memcpy(run, s, n);
		run[n] = 0;
		if (custom) fn(fonts[fi], 1.0f, font_baseline[fi], run, ctx);
		else fn(NULL, sys_scale, sys_baseline * sys_scale, run, ctx);
		s += n;
	}
}

static void measure_run(C2D_Font f, float scale, float baseline, const char *run, void *ctx)
{
	C2D_Text t;
	float w = 0;
	C2D_TextBufClear(measure_buf);
	C2D_TextFontParse(&t, f, measure_buf, run);
	C2D_TextGetDimensions(&t, scale, scale, &w, NULL);
	*(float *)ctx += w;
}

float font_measure(const char *s, float px)
{
	float w = 0;
	for_each_run(s, px, measure_run, &w);
	return w;
}

typedef struct { float x, y_baseline; u32 color; } draw_ctx_t;

static void draw_run(C2D_Font f, float scale, float baseline, const char *run, void *vctx)
{
	draw_ctx_t *c = vctx;
	C2D_Text t;
	C2D_TextFontParse(&t, f, draw_buf, run);
	C2D_TextOptimize(&t);
	float w = 0;
	C2D_TextGetDimensions(&t, scale, scale, &w, NULL);
	// Align every run on one shared baseline, then snap to whole pixels.
	float y = floorf(c->y_baseline - baseline + 0.5f);
	C2D_DrawText(&t, C2D_WithColor, floorf(c->x + 0.5f), y, 0.5f, scale, scale, c->color);
	c->x += w;
}

float font_draw(const char *s, float x, float y, float px, u32 color)
{
	// Layout coordinates were designed around the system font, so keep its
	// baseline position as the reference for every font.
	draw_ctx_t c = { x, y + sys_baseline * (px / sys_line), color };
	for_each_run(s, px, draw_run, &c);
	return c.x - x;
}
